#!/usr/bin/env bash
# clean.sh — remove bbport's generated build artifacts.
#
# The default targets are all regenerated by build.sh. Saves, settings and logs
# are kept unless --deep is given, which asks for confirmation first.
set -euo pipefail
cd -- "$(dirname -- "$0")/.."

# Fixed relative paths only. The script never builds a path from a variable or
# from user input, so an unset or empty variable can never reach rm.
readonly DEFAULT_TARGETS=(
    out
    dist
    pgo
    packaging/runtime-paths.nix
    fsr4_shaders
    fsr4_411
)
readonly DEEP_TARGETS=(
    user
    bbport.ini
    last_run.log
    logs
    mods.json
    patches.json
    vkd3d-proton.cache
)
readonly SUBMODULE_DIR=gpu/third_party/fsr-vulkan

deep=0
submodule=0
dry_run=0
assume_yes=0
total_kib=0
removed_count=0

usage() {
    cat <<'EOF'
Usage: bash scripts/clean.sh [options]

Removes bbport's generated build artifacts. Run it from anywhere: the script
changes to the repository root itself.

Default (safe) targets, all regenerated by the next build:
  out/  dist/  pgo/  packaging/runtime-paths.nix  fsr4_shaders/  fsr4_411/
  and every __pycache__/ directory (the .git tree is skipped).
Saves, settings and local data are kept: user/, bbport.ini, last_run.log, logs/.

Options:
  --deep, --all   Also remove user/, bbport.ini, last_run.log, logs/, mods.json,
                  patches.json, vkd3d-proton.cache, root *.spv/*.orig/*.dll and
                  tools/fsr4cap/*.exe. This deletes saves and settings, so it
                  asks for confirmation unless -y is passed.
  --submodule     Also run 'git -C gpu/third_party/fsr-vulkan checkout -- .' to
                  undo the FSR patches build.sh applied. The next build applies
                  them again.
  -n, --dry-run   List what would be removed and delete nothing.
  -y, --yes       Skip the --deep confirmation prompt.
  -h, --help      Show this help.

Safety: dist/ only holds the gamedata/CUSA03173 symlink to the game dump;
removing dist/ deletes that symlink, never the game dump it points to.
EOF
}

while (($#)); do
    case $1 in
        --deep|--all) deep=1 ;;
        --submodule) submodule=1 ;;
        -n|--dry-run) dry_run=1 ;;
        -y|--yes) assume_yes=1 ;;
        -h|--help) usage; exit 0 ;;
        *) echo "clean.sh: unknown option: $1" >&2; usage >&2; exit 2 ;;
    esac
    shift
done

human_size() { du -sh -- "$1" 2>/dev/null | cut -f1 || true; }
size_kib() { du -sk -- "$1" 2>/dev/null | cut -f1 || true; }

format_kib() {
    if command -v numfmt >/dev/null 2>&1; then
        numfmt --to=iec --suffix=B $(( $1 * 1024 ))
    else
        printf '%s KiB' "$1"
    fi
}

# remove_path is the only place that deletes. It is safe by construction: it
# refuses anything but a fixed relative path, and only removes paths that exist.
remove_path() {
    local path=$1
    if [[ -z $path || $path == /* || $path == . || $path == .. || $path == *..* ]]; then
        echo "clean.sh: refusing to remove unsafe path: '$path'" >&2
        exit 1
    fi
    [[ -e $path || -L $path ]] || return 0

    local human kib
    human=$(human_size "$path")
    kib=$(size_kib "$path")
    human=${human:-?}
    kib=${kib:-0}

    if ((dry_run)); then
        printf '  would remove  %-42s %s\n' "$path" "$human"
    else
        rm -rf -- "$path"
        printf '  removed       %-42s %s\n' "$path" "$human"
    fi
    total_kib=$((total_kib + kib))
    removed_count=$((removed_count + 1))
}

if ((deep && !assume_yes && !dry_run)); then
    echo '--deep removes saves and settings (user/, bbport.ini, logs/, ...).'
    read -r -p 'Continue? [y/N] ' reply
    case $reply in
        [yY]|[yY][eE][sS]) ;;
        *) echo 'Aborted.'; exit 0 ;;
    esac
fi

if ((dry_run)); then
    echo 'clean.sh: dry run — nothing will be deleted.'
else
    echo 'clean.sh: removing generated build artifacts'
fi

if [[ -e dist ]]; then
    echo 'Note: dist/ holds only the gamedata/CUSA03173 symlink; the game dump it points to is not touched.'
fi

for path in "${DEFAULT_TARGETS[@]}"; do
    remove_path "$path"
done

while IFS= read -r dir; do
    remove_path "$dir"
done < <(find . -path ./.git -prune -o -type d -name __pycache__ -print)

if ((deep)); then
    for path in "${DEEP_TARGETS[@]}"; do
        remove_path "$path"
    done
    shopt -s nullglob
    for path in *.spv *.orig *.dll tools/fsr4cap/*.exe; do
        remove_path "$path"
    done
    shopt -u nullglob
fi

if ((submodule)); then
    if [[ -d $SUBMODULE_DIR ]]; then
        if ((dry_run)); then
            printf '  would restore %s (git checkout -- .)\n' "$SUBMODULE_DIR"
        else
            git -C "$SUBMODULE_DIR" checkout -- .
            printf '  restored      %-42s %s\n' "$SUBMODULE_DIR" 'FSR patches reverted'
        fi
    fi
fi

if ((removed_count == 0)); then
    echo 'Nothing to remove: no generated artifacts found.'
else
    if ((dry_run)); then
        printf 'Would reclaim %s (%d item(s)).\n' "$(format_kib "$total_kib")" "$removed_count"
    else
        printf 'Reclaimed %s (%d item(s)).\n' "$(format_kib "$total_kib")" "$removed_count"
    fi
fi
